/* Общая логика отдельных HTML-экранов. Все изменения остаются в локальном макете. */
(() => {
'use strict';
const KEY='analystgym:admin-prototype:v1';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uid=p=>p+'-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,6);
const seed={courses:[{id:'sa-middle',title:'Системный анализ: от требований к API',description:'Практический курс о проектировании систем. От бизнес-процесса до работающего контракта интеграции.',audience:'Аналитики, которые хотят уверенно проектировать интеграции',level:'Базовый → Продвинутый',slug:'system-analysis',status:'draft',completion:'required',modules:[{id:'m1',title:'Основы взаимодействия систем',description:'HTTP, контракты и способы передачи данных',lessons:[{id:'l1',title:'HTTP: язык взаимодействия систем',minutes:25,free:true,blocks:[{id:'b1',type:'heading',text:'Каждый запрос — начало диалога'},{id:'b2',type:'text',text:'Приложения общаются с помощью запросов и ответов. Разберём, из чего складывается HTTP-запрос, как сервер понимает намерение клиента и где искать результат.\n\nПредставьте сервис заявок: клиент запрашивает список, а сервер возвращает данные и статус операции.'},{id:'b3',type:'table',text:'Часть запроса | Пример | Назначение\nМетод | GET | Получить ресурс\nПуть | /applications | Обратиться к заявкам\nЗаголовок | Accept: application/json | Выбрать формат ответа'},{id:'b4',type:'callout',text:'URL fragment (#section) остаётся в браузере и не передаётся серверу в HTTP-запросе.'}],tests:[{id:'t1',title:'Проверяем понимание HTTP',required:true,passing:70,questions:[{id:'q1',type:'single',text:'Какой заголовок описывает формат отправленного тела?',options:['Accept','Content-Type','Authorization'],correct:[1],explanation:'Content-Type описывает формат тела сообщения. Accept сообщает, какой формат ответа ожидает клиент.'}]}],practices:['p1'],materials:[{id:'a1',title:'Памятка: структура HTTP-запроса',type:'link',value:'https://www.rfc-editor.org/rfc/rfc9110.html',description:'Официальная спецификация HTTP Semantics'}]},{id:'l2',title:'Создание заявки и идемпотентность',minutes:35,free:false,blocks:[{id:'b5',type:'heading',text:'Что произойдёт при повторном запросе?'},{id:'b6',type:'text',text:'Повторная отправка не должна создавать лишнюю заявку. Исследуйте поведение API и сформулируйте требования к обработке ключа идемпотентности.'}],tests:[],practices:['p2'],materials:[]}]},{id:'m2',title:'Данные и SQL',description:'Модель данных и практика работы с запросами',lessons:[{id:'l3',title:'SELECT и связи между таблицами',minutes:30,free:false,blocks:[{id:'b7',type:'heading',text:'Собираем данные из нескольких таблиц'}],tests:[],practices:['p3'],materials:[]}]}]}],practices:[{id:'p1',type:'http',title:'Первый запрос к API заявок',scenario:'http-basics',instructions:'Получите список заявок. Найдите статус ответа и заголовок Content-Type.',required:true,method:'GET',path:'/applications',body:'',query:'status=NEW',headers:'Accept: application/json',auth:'none',steps:['Выполните GET /applications','Найдите заголовок Content-Type'],checks:'Ответ 200; возвращён массив заявок',config:'{}'},{id:'p2',type:'http',title:'Повторный POST с тем же ключом',scenario:'application-idempotency',instructions:'Создайте заявку и повторите запрос с тем же ключом. Сравните ID.',required:true,method:'POST',path:'/applications',body:'{\n  "customerId": "customer-42"\n}',query:'',headers:'Content-Type: application/json\nIdempotency-Key: application-001',auth:'bearer',steps:['Создайте заявку','Повторите тот же запрос с тем же ключом'],checks:'Один объект после двух запросов; совпадают ID',config:'{}'},{id:'p3',type:'sql',title:'Найти клиентов без заявок',scenario:'sql-select-join',instructions:'Найдите клиентов, у которых нет ни одной заявки. Верните id и name.',required:true,query:'',sql:'SELECT c.id, c.name\nFROM customers c\nLEFT JOIN applications a ON a.customer_id = c.id\nWHERE a.id IS NULL;',checks:'Столбцы id, name; ожидаемый набор строк; порядок не важен',config:'{}'}]};
let state;try{state=JSON.parse(localStorage.getItem(KEY))||structuredClone(seed)}catch{state=structuredClone(seed)}
const params=new URLSearchParams(location.search), page=document.body.dataset.page||'courses';
let course=state.courses.find(c=>c.id===params.get('course'))||state.courses[0];
let lessons=()=>course?.modules.flatMap(m=>m.lessons.map(l=>({...l,moduleId:m.id})))||[];
let lesson=course?.modules.flatMap(m=>m.lessons).find(l=>l.id===params.get('lesson'))||course?.modules[0]?.lessons[0];
let module=course?.modules.find(m=>m.id===(params.get('module')||lessons().find(l=>l.id===lesson?.id)?.moduleId))||course?.modules[0];
const countLabel=(n,one,few,many)=>n+' '+((n%100>=11&&n%100<=14)?many:n%10===1?one:n%10>=2&&n%10<=4?few:many);
const types={http:'HTTP / REST',sql:'SQL',soap:'SOAP',kafka:'Kafka',queue:'Очереди сообщений'};
const scenarios={http:[['http-basics','HTTP · структура запроса'],['application-idempotency','REST · идемпотентность'],['rest-crud','REST · методы и параметры'],['file-upload','REST · загрузка файлов'],['http-auth','HTTP · аутентификация']],sql:[['sql-select-join','SQL · SELECT и JOIN'],['sql-aggregate','SQL · GROUP BY'],['sql-insert','SQL · INSERT'],['sql-update-delete','SQL · UPDATE / DELETE'],['sql-create-table','SQL · CREATE TABLE']],soap:[['soap-envelope','SOAP · Envelope и Fault']],kafka:[['kafka-publish-consume','Kafka · публикация и чтение']],queue:[['queue-delivery','Очередь · подтверждение и повторная доставка']]};
const save=()=>{try{localStorage.setItem(KEY,JSON.stringify(state));return true}catch{toast('Хранилище браузера недоступно. Изменения не сохранены.');return false}};
function url(file,extra={}){const p=new URLSearchParams();if(course)p.set('course',course.id);if(lesson)p.set('lesson',lesson.id);Object.entries(extra).forEach(([k,v])=>v==null?p.delete(k):p.set(k,v));return file+'.html'+(p.size?'?'+p:'')}
const link=(file,label,cls='',extra={})=>`<a class="btn ${cls}" href="${url(file,extra)}">${label}</a>`;
const field=(label,name,value='',kind='input',hint='')=>`<label class="field"><span>${label}</span>${kind==='textarea'?`<textarea name="${name}">${esc(value)}</textarea>`:`<input name="${name}" value="${esc(value)}" ${kind==='number'?'type="number" min="1" max="999"':kind==='url'?'type="url"':''}>`}${hint?`<small>${hint}</small>`:''}</label>`;
const select=(label,name,options,value)=>`<label class="field"><span>${label}</span><select name="${name}">${options.map(o=>{const [v,t]=Array.isArray(o)?o:[o,o];return `<option value="${esc(v)}" ${v===value?'selected':''}>${esc(t)}</option>`}).join('')}</select></label>`;
const check=(label,name,on=true)=>`<label class="check"><input type="checkbox" name="${name}" ${on?'checked':''}>${label}</label>`;
const badge=(text,color='')=>`<span class="badge ${color}">${text}</span>`;
const button=(label,action,arg='',cls='')=>`<button type="button" class="btn ${cls}" data-action="${action}" data-id="${esc(arg)}">${label}</button>`;
const submit=(label='Сохранить',cls='primary')=>`<button class="btn ${cls}" type="submit" form="editor">${label}</button>`;
const head=(title,desc,actions='')=>`<div class="pagehead"><div><div class="eyebrow">РЕДАКТОРСКАЯ / ${page.startsWith('course')?'КУРСЫ':'КОНТЕНТ'}</div><h1>${title}</h1><p>${desc}</p></div><div class="actions">${actions}</div></div>`;
const crumb=()=>`<nav class="crumbs" aria-label="Хлебные крошки"><a href="index.html">Курсы</a>${course?`<span>/</span><a href="${url('course-outline')}">${esc(course.title)}</a>`:''}${lesson&&page.startsWith('lesson')?`<span>/</span><span>${esc(lesson.title)}</span>`:''}</nav>`;
function shell(content){document.getElementById('app').innerHTML=`<header><a class="brand" href="index.html">Analyst<span>GYM</span><small>Редакторская</small></a><div class="profile"><span>Локальный макет</span><span class="avatar">АК</span><span>Автор курса</span></div></header><div class="app"><aside><a class="navlink ${page==='courses'?'active':''}" href="index.html"><span class="navicon">▦</span>Все курсы</a><a class="navlink ${page==='practice-library'?'active':''}" href="${url('practice-library',{scope:'all'})}"><span class="navicon">⌘</span>Тренажёры</a>${course?`<div class="side-label">ТЕКУЩИЙ КУРС</div><div class="side-course">${esc(course.title)}</div><a class="navlink ${page==='course-outline'?'active':''}" href="${url('course-outline')}">☷ Программа курса</a><a class="navlink ${page==='course-settings'?'active':''}" href="${url('course-settings')}">⚙ Настройки</a><div class="side-tree">${course.modules.map(m=>`<div class="tree-module">${esc(m.title)}</div>${m.lessons.map(l=>`<a class="tree-lesson ${l.id===lesson?.id&&page!=='courses'?'current':''}" href="${url('lesson-lecture',{lesson:l.id})}">${esc(l.title)}</a>`).join('')}`).join('')}</div>`:''}<div class="side-bottom">Курс → Модуль → Урок<br>Все изменения этого макета<br>сохраняются только в браузере.<br><br><a href="reset.html">Сбросить демо-данные</a></div></aside><main>${crumb()}${content}</main></div><div id="toast" role="status" aria-live="polite"></div>`;document.title=(document.querySelector('h1')?.textContent||'Редакторская')+' — AnalystGYM'}
function lessonHead(tab){const flat=lessons(),index=flat.findIndex(l=>l.id===lesson.id);return `<div class="lesson-top"><div><div class="eyebrow">${esc(module?.title)} · УРОК ${index+1}</div><h1>${esc(lesson.title)}</h1><p>${lesson.minutes} минут · ${badge('Черновик')} <a href="${url('lesson-settings')}" style="margin-left:12px">Настройки урока ↗</a></p></div><div class="lesson-control"><nav class="lesson-pagination" aria-label="Навигация по урокам">${index>0?link('lesson-'+tab,'← Предыдущий','',{lesson:flat[index-1].id}):'<span>Начало модуля</span>'}<span>${index+1} / ${flat.length}</span>${index<flat.length-1?link('lesson-'+tab,'Следующий →','',{lesson:flat[index+1].id}):'<span>Последний урок</span>'}</nav><div class="actions">${link('lesson-preview','◉ Предпросмотр')}${link('course-publish','Проверить курс','primary')}</div></div></div><nav class="tabs lesson-tabs" aria-label="Разделы урока">${[['lecture','Лекция'],['tests','Тесты'],['practice','Практика'],['materials','Материалы']].map(([t,n])=>`<a class="${tab===t?'active':''}" href="${url('lesson-'+t)}">${n} ${t==='tests'?`<small>${lesson.tests.length}</small>`:t==='practice'?`<small>${lesson.practices.length}</small>`:''}</a>`).join('')}</nav>`}
const empty=(title,text,cta)=>`<div class="empty"><span class="symbol" style="margin:auto">＋</span><h2>${title}</h2><p>${text}</p>${cta}</div>`;
const support=(title,text,items=[])=>`<div class="panel sticky-help"><div class="eyebrow">В ПОМОЩЬ АВТОРУ</div><h2>${title}</h2><p class="muted" style="font-size:12px;margin-top:12px">${text}</p><ul class="mini-list">${items.map(i=>`<li>${i}</li>`).join('')}</ul></div>`;
function render(){
if(page==='courses'){shell(head('Курсы','Собирайте программу, добавляйте практику и готовьте материалы к публикации.',link('course-new','＋ Создать курс','primary'))+`<div class="stats"><div class="stat"><small>Всего курсов</small><strong>${state.courses.length}</strong></div><div class="stat"><small>В работе</small><strong>${state.courses.filter(c=>c.status!=='published').length}</strong></div><div class="stat"><small>Опубликовано</small><strong>${state.courses.filter(c=>c.status==='published').length}</strong></div></div><div class="toolbar"><input id="search" aria-label="Найти курс" placeholder="⌕ Найти курс по названию"><select id="statusFilter" aria-label="Статус курса" style="width:180px"><option value="all">Все статусы</option><option value="draft">Черновики</option><option value="published">Опубликованные</option></select></div><div id="courseList">${state.courses.map(c=>`<article class="course-card" data-title="${esc(c.title.toLowerCase())}" data-status="${c.status}"><div class="course-logo">SA</div><div><h3><a href="${url('course-outline',{course:c.id,lesson:null})}">${esc(c.title)}</a></h3><p>${esc(c.description)}</p><div class="course-meta"><span>${countLabel(c.modules.length,'модуль','модуля','модулей')}</span><span>${countLabel(c.modules.reduce((n,m)=>n+m.lessons.length,0),'урок','урока','уроков')}</span><span>${esc(c.level)}</span></div></div><div class="actions">${badge(c.status==='published'?'Опубликован':'Черновик',c.status==='published'?'green':'amber')}${link('course-outline','Открыть →','',{course:c.id,lesson:null})}</div></article>`).join('')}</div><p id="noResults" class="muted" hidden>Курсы не найдены. Измените запрос или фильтр.</p>`);return}
if(page==='course-new'||page==='course-settings'){const fresh=page==='course-new',c=fresh?{}:course;shell(head(fresh?'Новый курс':'Настройки курса',fresh?'Начните с названия и результата обучения. Программу можно собрать следующим шагом.':'Описание, доступ и правила завершения курса.',link(fresh?'index':'course-outline','Отмена')+submit(fresh?'Создать курс':'Сохранить'))+`<form id="editor" data-form="course"><div class="grid"><div><section class="panel"><div class="panel-head"><h2>Основная информация</h2>${badge('Шаг 1 · О курсе')}</div>${field('Название курса *','title',c.title)}${field('Краткое описание *','description',c.description,'textarea')}${field('Для кого этот курс','audience',c.audience)}<div class="fields">${field('Адрес курса','slug',c.slug,'input','Например: system-analysis')}${select('Уровень','level',['Базовый','Базовый → Продвинутый','Продвинутый'],c.level)}</div></section><section class="panel"><h2 style="margin-bottom:20px">Прохождение и доступ</h2>${select('Условие завершения','completion',[['required','Выполнить обязательные задания'],['read','Отметить уроки прочитанными']],c.completion||'required')}${check('Показывать программу до начала обучения','visible',c.visible!==false)}<div class="note">Бесплатный доступ настраивается отдельно для каждого урока.</div></section></div>${support('Сначала — результат','Сформулируйте, что участник сможет сделать после курса. Затем разбейте путь на модули и уроки.',['01 · Настройте курс','02 · Соберите программу','03 · Добавьте содержание','04 · Проверьте публикацию'])}</div></form>`);return}
if(page==='course-outline'){shell(head(esc(course.title),'Программа курса. У каждого урока есть лекция, тесты, практика и материалы.',link('lesson-order','↕ Порядок уроков')+link('course-publish','Публикация','primary'))+`<nav class="tabs"><a class="active" href="${url('course-outline')}">Программа</a><a href="${url('course-settings')}">Настройки курса</a></nav>${course.modules.length?course.modules.map((m,i)=>`<section class="module"><div class="module-head"><span class="mono">${String(i+1).padStart(2,'0')}</span><div class="grow"><h3>${esc(m.title)}</h3><small>${countLabel(m.lessons.length,'урок','урока','уроков')}</small></div>${link('module-edit','Настроить','ghost',{module:m.id})}</div>${m.lessons.map((l,j)=>`<div class="lesson-row"><span class="number">${j+1}</span><div class="grow"><h3><a href="${url('lesson-lecture',{lesson:l.id})}">${esc(l.title)}</a></h3><small>${l.minutes} мин · ${countLabel(l.blocks.length,'блок','блока','блоков')} · ${countLabel(l.tests.length,'тест','теста','тестов')} · ${countLabel(l.practices.length,'практика','практики','практик')}</small></div>${l.free?badge('Открытый урок','green'):''}${link('lesson-lecture','Редактировать →','',{lesson:l.id})}</div>`).join('')}<a class="module-add" href="${url('lesson-new',{module:m.id})}">＋ Добавить урок</a></section>`).join(''):empty('Первый модуль','Объедините уроки одной темой.',link('module-new','＋ Добавить модуль','primary'))}<div class="bottom-actions">${link('module-new','＋ Добавить модуль')}</div>`);return}
if(page==='module-new'||page==='module-edit'){const fresh=page==='module-new',m=fresh?{}:module;shell(head(fresh?'Добавить модуль':'Настройки модуля','Модуль объединяет уроки одной темой.',link('course-outline','Отмена')+submit(fresh?'Добавить модуль':'Сохранить'))+`<form id="editor" data-form="module"><div class="grid"><section class="panel">${field('Название модуля *','title',m.title)}${field('Описание','description',m.description,'textarea')}${select('Положение в программе','position',[['end','В конце курса'],...course.modules.filter(x=>x.id!==m.id).map(x=>['before:'+x.id,'Перед: '+x.title])],fresh?'end':(course.modules[course.modules.findIndex(x=>x.id===m.id)+1]?'before:'+course.modules[course.modules.findIndex(x=>x.id===m.id)+1].id:'end'))}${!fresh?`<div class="divider"></div>${link('delete','Удалить модуль','danger',{entity:'module',entityId:m.id})}`:''}</section>${support('Одна тема — один модуль','Модуль можно переименовать или переместить, не теряя содержание уроков.')}</div></form>`);return}
if(page==='lesson-new'||page==='lesson-settings'){const fresh=page==='lesson-new',l=fresh?{}:lesson;shell(head(fresh?'Новый урок':'Настройки урока','Определите место урока в программе и ожидаемый результат.',link(fresh?'course-outline':'lesson-lecture','Отмена')+submit(fresh?'Создать урок':'Сохранить'))+`<form id="editor" data-form="lesson"><div class="grid"><section class="panel">${field('Название урока *','title',l.title)}${select('Модуль','module',course.modules.map(m=>[m.id,m.title]),module?.id)}${field('Результат урока','outcome',l.outcome,'textarea')}${field('Время прохождения, минут','minutes',l.minutes||20,'number')}${check('Открытый урок — доступен без покупки курса','free',!!l.free)}${!fresh?`<div class="divider"></div><div class="actions">${link('lesson-order','Переместить урок')}${button('Создать копию','duplicate-lesson',l.id)}${link('delete','Удалить урок','danger',{entity:'lesson',entityId:l.id})}</div>`:''}</section>${support('Четыре части урока','После создания откроется лекция. Тесты, практику и материалы можно наполнить независимо.',['Лекция · объяснить','Тесты · проверить понимание','Практика · применить','Материалы · сохранить под рукой'])}</div></form>`);return}
if(page==='lesson-lecture'){shell(lessonHead('lecture')+`<div class="grid"><div>${lesson.blocks.length?lesson.blocks.map(blockCard).join(''):empty('Здесь начнётся урок','Добавьте первый текстовый блок или готовую практику.',link('block-add','＋ Добавить блок','primary'))}${lesson.blocks.length?`<a class="add-block" href="${url('block-add')}">＋ Добавить блок</a>`:''}</div>${support('Соберите историю урока','Чередуйте объяснение и действие. Тест или тренажёр можно вставить прямо между абзацами.',['Блоки можно перемещать ↑ ↓','Нажмите «Изменить» для редактирования','Задания также доступны в своих разделах'])}</div>`);return}
if(page==='block-add'){const btypes=[['heading','H₁','Заголовок','Обозначить новую мысль'],['text','¶','Текст','Объяснение с форматированием'],['table','▦','Таблица','Структура, сравнение, контракт'],['callout','!','Выделенный фрагмент','Акцент или важное замечание'],['test','✓','Тест в лекции','Вставить проверку понимания'],['practice','⌘','Практика в лекции','Добавить интерактивное упражнение']];shell(head('Добавить блок','Выберите, что появится следующим в лекции.',link('lesson-lecture','← В лекцию'))+`<div class="selection-grid">${btypes.map(([t,i,n,d])=>`<a class="selection" href="${url(t==='test'?'test-edit':t==='practice'?'practice-new':'block-edit',{type:t,inline:t==='test'||t==='practice'?'1':null})}"><span class="symbol">${i}</span><h3>${n}</h3><p>${d}</p></a>`).join('')}</div>`);return}
if(page==='block-edit'){const b=lesson.blocks.find(b=>b.id===params.get('block')),type=b?.type||params.get('type')||'text';shell(head(b?'Редактировать блок':'Новый блок',({heading:'Заголовок раздела',text:'Текст лекции с базовым форматированием',table:'Строки таблицы; столбцы разделяются знаком |',callout:'Ключевая мысль, замечание или предупреждение'})[type],link('lesson-lecture','Отмена')+submit('Сохранить блок'))+`<form id="editor" data-form="block" data-type="${type}"><div class="grid"><section class="panel">${type==='text'?`<div class="toolbar">${button('Жирный','format','bold')}${button('Курсив','format','italic')}${button('Ссылка','format','link')}</div>`:''}${field('Содержание *','text',b?.text||'','textarea',type==='text'?'Поддерживаются **жирный**, *курсив* и [ссылка](https://example.com).':'')}${type==='table'?'<div class="note">Первая строка — названия столбцов. Например: Поле | Тип | Описание</div>':''}</section>${support('Коротко и по делу','Один блок — одна законченная мысль. Содержание появится в лекции после сохранения.')}</div></form>`);return}
if(page==='lesson-tests'){shell(lessonHead('tests')+head('Тесты урока','Проверки понимания. Их можно проходить отдельно или встретить внутри лекции.',link('test-edit','＋ Добавить тест','primary'))+(lesson.tests.length?lesson.tests.map(t=>`<article class="list-card"><div class="row"><div class="grow">${badge('ТЕСТ','purple')}<h3>${esc(t.title)}</h3><p>${countLabel(t.questions.length,'вопрос','вопроса','вопросов')} · порог ${t.passing}% · ${t.required?'Обязательный':'Для самопроверки'}</p></div></div><div class="actions">${link('test-edit','Редактировать','',{test:t.id})}${button('Вставить в лекцию','embed-test',t.id)}${link('delete','Удалить','ghost',{entity:'test',entityId:t.id})}</div></article>`).join(''):empty('Проверим понимание?','Добавьте вопросы, правильные ответы и объяснения.',link('test-edit','Создать первый тест','primary'))));return}
if(page==='test-edit'){const t=lesson.tests.find(t=>t.id===params.get('test'));shell(head(t?'Редактировать тест':'Новый тест','Вопросы, варианты ответов и обратная связь.',link('lesson-tests','Отмена')+submit('Сохранить тест'))+`<form id="editor" data-form="test"><div class="grid"><div><section class="panel">${field('Название теста *','title',t?.title||'')}${check('Обязательный для завершения урока','required',t?.required!==false)}${field('Проходной результат, %','passing',t?.passing||70,'number')}</section><div id="questions">${(t?.questions||[{id:uid('q'),type:'single',text:'',options:['',''],correct:[0],explanation:''}]).map(questionCard).join('')}</div>${button('＋ Добавить вопрос','add-question')}</div>${support('Объясните ответ','Хорошее объяснение помогает разобраться и после правильного ответа. Для нескольких правильных вариантов выберите соответствующий тип вопроса.',['Один правильный ответ','Несколько правильных ответов','Обратная связь после ответа'])}</div></form>`);return}
if(page==='lesson-practice'){shell(lessonHead('practice')+head('Практика урока','Упражнения, в которых участник применяет знания.',link('practice-library','Из библиотеки')+link('practice-new','＋ Добавить практику','primary'))+(lesson.practices.length?lesson.practices.map(id=>state.practices.find(p=>p.id===id)).filter(Boolean).map(p=>practiceCard(p,false)).join(''):empty('От теории к действию','Выберите готовое упражнение или создайте своё.',link('practice-new','Выбрать тип практики','primary'))));return}
if(page==='practice-new'){shell(head('Выберите тип практики','Настройте учебное задание. Подключения и ограничения среды определяет платформа.',link('lesson-practice','Отмена'))+`<div class="selection-grid">${Object.entries(types).map(([t,n])=>`<a class="selection" href="${url('practice-edit',{type:t,inline:params.get('inline')})}"><span class="symbol">${({http:'↔',sql:'SQL',soap:'XML',kafka:'⇢',queue:'≋'})[t]}</span><h3>${n}</h3><p>${({http:'Методы, URL, заголовки, тело и аутентификация',sql:'Выборки, изменение данных и работа со схемой',soap:'Сообщения, операции и SOAP Fault',kafka:'Топики, публикация и чтение событий',queue:'Доставка, подтверждения и повторная обработка'})[t]}</p>${['soap','kafka','queue'].includes(t)?'<small>Концепция редактора · сценарии уточняются</small>':''}</a>`).join('')}</div>`);return}
if(page==='practice-edit'){const p=state.practices.find(p=>p.id===params.get('practice')),type=p?.type||params.get('type')||'http';shell(head(p?'Редактировать практику':'Новая практика · '+types[type],'Условие и стартовая рабочая область ученика.',link('lesson-practice','Отмена')+submit('Сохранить практику'))+`<form id="editor" data-form="practice" data-type="${type}"><div class="grid"><div><section class="panel">${field('Название упражнения *','title',p?.title)}${select('Учебный сценарий','scenario',scenarios[type],p?.scenario||scenarios[type][0][0])}${field('Условие *','instructions',p?.instructions,'textarea')}${check('Обязательное упражнение','required',p?.required!==false)}</section><section class="panel"><div class="panel-head"><h2>Стартовая рабочая область</h2>${badge(types[type])}</div>${type==='http'?`<div class="fields">${select('Метод','method',['GET','POST','PUT','PATCH','DELETE','HEAD','OPTIONS'],p?.method||'GET')}${field('Путь','path',p?.path||'/applications')}</div>${field('Query-параметры','query',p?.query||'')}${field('Заголовки','headers',p?.headers||'Accept: application/json','textarea')}${select('Учебная аутентификация','auth',[['none','Без аутентификации'],['bearer','Bearer token'],['basic','Basic'],['apiKey','API key'],['oauth2','OAuth 2.0']],p?.auth||'none')}${select('Формат тела','bodyMode',['Нет тела','Raw JSON','Raw text','Raw XML','Multipart / файл'],p?.bodyMode||(p?.body?'Raw JSON':'Нет тела'))}${field('Тело запроса / описание частей multipart','body',p?.body||'','textarea')}`:type==='sql'?`<label class="field"><span>Стартовый SQL</span><textarea name="sql" class="code">${esc(p?.sql||'SELECT *\nFROM applications;')}</textarea></label><div class="note">Участник работает с личной фикстурой. Для CREATE TABLE предусмотрены лимиты объектов и повторная попытка через сброс.</div>`:field(type==='soap'?'Стартовый XML':'Стартовое сообщение','body',p?.body||'','textarea')}${field('Шаги упражнения · по одному на строку','steps',(p?.steps||[]).join('\n'),'textarea')}</section><section class="panel"><h2 style="margin-bottom:18px">Проверка результата</h2>${field('Что должно получиться *','checks',p?.checks,'textarea','Авторское описание для обсуждения механизма проверки. В макете реальное исполнение не подключено.')}</section></div><div><section class="panel"><div class="eyebrow">КОНФИГУРАЦИЯ БЛОКА</div><h2>JSON</h2><p class="muted" style="font-size:12px;margin:12px 0">Собирается из полей. Можно изменить вручную и применить.</p><textarea id="configJson" class="code" aria-label="JSON конфигурации практики"></textarea><div class="bottom-actions">${button('Применить JSON','apply-json')}</div><div id="jsonError" class="error-text" role="alert"></div></section><div class="note">Адреса серверов, подключения к БД, секреты и лимиты здесь не редактируются.</div>${p&&state.courses.some(c=>c.modules.some(m=>m.lessons.some(l=>l.id!==lesson.id&&l.practices.includes(p.id))))?'<p class="footer-info">Это упражнение используется и в других уроках. Сохранение обновит общую практику.</p>':''}</div></div></form>`);syncJson();return}
if(page==='practice-library'){const all=params.get('scope')==='all';shell(head('Библиотека тренажёров',all?'Переиспользуемые упражнения платформы.':'Добавьте существующее упражнение в текущий урок.',link('practice-new','＋ Создать практику','primary'))+`<div class="toolbar"><input id="practiceSearch" placeholder="⌕ Найти упражнение" aria-label="Найти упражнение"></div><div id="practiceList">${state.practices.map(p=>`<div data-title="${esc(p.title.toLowerCase())}">${practiceCard(p,true)}</div>`).join('')}</div><p id="noPractice" class="muted" hidden>Упражнения не найдены.</p>`);return}
if(page==='lesson-materials'){shell(lessonHead('materials')+head('Материалы урока','Памятки, ссылки, файлы и шаблоны рабочих артефактов.',link('material-edit','＋ Добавить материал','primary'))+(lesson.materials.length?lesson.materials.map(a=>`<article class="list-card"><div class="row"><span class="symbol">${a.type==='link'?'↗':'▤'}</span><div class="grow"><h3>${esc(a.title)}</h3><p>${esc(a.description||a.value)} · ${esc(a.type==='link'?'Ссылка':a.type==='template'?'Шаблон артефакта':'Файл')}</p></div>${link('material-edit','Изменить','',{material:a.id})}${link('delete','Удалить','ghost',{entity:'material',entityId:a.id})}</div></article>`).join(''):empty('Полезное под рукой','Добавьте ссылку, файл или шаблон артефакта.',link('material-edit','Добавить материал','primary'))));return}
if(page==='material-edit'){const a=lesson.materials.find(a=>a.id===params.get('material'));shell(head(a?'Редактировать материал':'Новый материал','Дополнительный ресурс или заготовка для работы участника.',link('lesson-materials','Отмена')+submit('Сохранить материал'))+`<form id="editor" data-form="material"><div class="grid"><section class="panel">${field('Название *','title',a?.title)}${select('Тип материала','type',[['link','Ссылка'],['file','Файл'],['template','Шаблон артефакта']],a?.type||'link')}${field('Описание','description',a?.description,'textarea')}<div id="materialLink">${field('URL *','value',a?.value,'url')}</div><div id="materialFile" hidden><label class="field"><span>Файл</span><input type="file" name="file"><small>Макет сохраняет только имя файла. Файл на сервер не загружается.</small></label>${a?.fileName?`<small>Выбран: ${esc(a.fileName)}</small>`:''}</div><div id="materialTemplate" hidden>${select('Работа с артефактом','artifactMode',[['create','Создать новый'],['continue','Продолжить существующий'],['revise','Доработать после обратной связи']],a?.artifactMode||'create')}${field('Ключ артефакта','artifactKey',a?.artifactKey||'integration-spec')}${field('Содержание шаблона','template',a?.template||'','textarea')}</div></section>${support('Артефакт развивается','В разных уроках можно продолжать одну работу участника. Используйте один ключ артефакта для связанного шаблона.')}</div></form>`);materialVisibility();return}
if(page==='lesson-order'){shell(head('Порядок уроков','Перетаскивайте уроки внутри модуля или используйте стрелки. Для переноса выберите другой модуль.',link('course-outline','Отмена')+button('Сохранить порядок','save-order','','primary'))+`<div class="note" style="margin-bottom:20px">Изменяется только порядок и принадлежность модулю. Содержание уроков сохраняется.</div><div id="orderModules">${course.modules.map((m,i)=>`<section class="module" data-module="${m.id}"><div class="module-head"><div class="grow"><h3>${esc(m.title)}</h3></div>${button('↑','module-up',m.id,'icon')}${button('↓','module-down',m.id,'icon')}</div><div class="order-list">${m.lessons.map(l=>`<div class="lesson-row order-row" draggable="true" data-lesson="${l.id}"><span class="number" aria-hidden="true">⠿</span><div class="grow"><h3>${esc(l.title)}</h3><small>${l.minutes} минут</small></div><select aria-label="Модуль для ${esc(l.title)}" data-move="${l.id}" style="width:200px">${course.modules.map(x=>`<option value="${x.id}" ${x.id===m.id?'selected':''}>${esc(x.title)}</option>`).join('')}</select>${button('↑','lesson-up',l.id,'icon')}${button('↓','lesson-down',l.id,'icon')}</div>`).join('')}</div></section>`).join('')}</div>`);bindDrag();return}
if(page==='lesson-preview'){shell(head('Предпросмотр урока','Так материал выглядит для участника.',link('lesson-lecture','← Вернуться в редактор'))+`<div class="preview-banner">Предпросмотр · учебные запросы и SQL имитируются, реальные среды не подключены.</div><article class="preview-content"><div class="eyebrow">${esc(module.title)}</div><h1 style="margin:12px 0 28px">${esc(lesson.title)}</h1>${lesson.blocks.map(b=>blockCard(b,true)).join('')}<div class="divider"></div><h2 style="margin-bottom:18px">Тесты и практика урока</h2>${lesson.tests.filter(t=>!lesson.blocks.some(b=>b.type==='test'&&b.ref===t.id)).map(testPreview).join('')}${lesson.practices.filter(id=>!lesson.blocks.some(b=>b.type==='practice'&&b.ref===id)).map(id=>state.practices.find(p=>p.id===id)).filter(Boolean).map(practicePreview).join('')}${lesson.materials.length?`<div class="panel"><h2>Материалы</h2><ul class="mini-list">${lesson.materials.map(a=>`<li>${a.type==='link'?`<a target="_blank" rel="noopener" href="${safeUrl(a.value)}">${esc(a.title)} ↗</a>`:esc(a.title)}</li>`).join('')}</ul></div>`:''}</article>`);return}
if(page==='course-publish'){const checks=publicationChecks();shell(head('Готовность к публикации','Проверьте содержание и завершённость программы перед открытием доступа.',link('course-outline','← В программу'))+`<div class="grid"><section class="panel"><div class="panel-head"><h2>Проверка курса</h2>${badge(checks.every(c=>c.ok)?'Можно публиковать':'Нужны исправления',checks.every(c=>c.ok)?'green':'amber')}</div>${checks.map(c=>`<div class="publish-check"><b style="color:${c.ok?'#478255':'#b78a3a'}">${c.ok?'✓':'!'}</b><div class="grow">${esc(c.text)}</div>${c.href?`<a href="${c.href}">Открыть →</a>`:''}</div>`).join('')}<div class="bottom-actions"><button class="btn primary" data-action="publish" ${checks.some(c=>!c.ok)?'disabled':''}>Опубликовать в макете</button></div></section>${support('Публикация — отдельный шаг','Сохранение меняет черновик. Эта кнопка меняет только демо-статус курса в браузере и не публикует данные в интернете.',['Проверено: '+countLabel(lessons().length,'урок','урока','уроков'),'Статус: '+(course.status==='published'?'опубликован':'черновик')])}</div>`);return}
if(page==='delete'){const entity=params.get('entity'),id=params.get('entityId'),title=entity==='lesson'?lesson.title:entity==='module'?module?.title:entity==='test'?lesson.tests.find(x=>x.id===id)?.title:lesson.materials.find(x=>x.id===id)?.title;shell(head('Удалить '+({lesson:'урок',module:'модуль',test:'тест',material:'материал'})[entity]+'?','Подтвердите действие перед изменением программы.')+`<div class="panel" style="max-width:720px"><h2>${esc(title)}</h2><p class="muted" style="margin:18px 0">${entity==='module'?'Будут удалены модуль и все входящие в него уроки.':entity==='lesson'?'Будут удалены урок, его лекция, тесты и привязки материалов. Общие тренажёры останутся в библиотеке.':'Объект будет удалён из этого урока.'}</p><div class="note warn">Это действие относится только к локальному макету.</div><div class="bottom-actions">${link(entity==='module'?'course-outline':entity==='lesson'?'lesson-settings':entity==='test'?'lesson-tests':'lesson-materials','Отмена')}${button('Удалить','confirm-delete',id,'danger')}</div></div>`);return}
if(page==='reset'){shell(head('Сбросить демо-данные?','Ваши изменения в макете будут заменены исходным примером.')+`<div class="panel"><p>Курсы, уроки и упражнения настоящего приложения не затрагиваются.</p><div class="bottom-actions">${link('index','Отмена')}${button('Восстановить пример','reset','','danger')}</div></div>`);return}
shell(empty('Урок пока не выбран','Откройте программу курса.',link('course-outline','В программу','primary')));
}
function safeUrl(v){try{const u=new URL(v);return ['http:','https:'].includes(u.protocol)?esc(u.href):'#'}catch{return '#'}}
function rich(text){return esc(text).replace(/\*\*(.+?)\*\*/g,'<strong>$1</strong>').replace(/\*([^*]+?)\*/g,'<em>$1</em>').replace(/\[([^\]]+)\]\((https?:\/\/[^\s)]+)\)/g,(_,t,u)=>`<a href="${safeUrl(u)}" target="_blank" rel="noopener">${t} ↗</a>`)}
function blockCard(b,preview=false){let body=b.type==='heading'?`<h2>${esc(b.text)}</h2>`:b.type==='table'?`<table>${b.text.split('\n').filter(Boolean).map((r,i)=>`<tr>${r.split('|').map(c=>`<${i?'td':'th'}>${esc(c.trim())}</${i?'td':'th'}>`).join('')}</tr>`).join('')}</table>`:b.type==='callout'?`<div class="note">${esc(b.text)}</div>`:b.type==='test'?preview?testPreview(lesson.tests.find(t=>t.id===b.ref)):`<div class="row"><span class="symbol">✓</span><div><h3>Тест внутри лекции</h3><p>${esc(lesson.tests.find(t=>t.id===b.ref)?.title||'Тест удалён')}</p></div></div>`:b.type==='practice'?preview?practicePreview(state.practices.find(p=>p.id===b.ref)):`<div class="row"><span class="symbol">⌘</span><div><h3>Практика внутри лекции</h3><p>${esc(state.practices.find(p=>p.id===b.ref)?.title||'Практика удалена')}</p></div></div>`:`<p>${rich(b.text)}</p>`;return `<section class="block"><div class="block-top"><span>⠿</span><span class="grow">${({heading:'ЗАГОЛОВОК',text:'ТЕКСТ',table:'ТАБЛИЦА',callout:'АКЦЕНТ',test:'ТЕСТ',practice:'ПРАКТИКА'})[b.type]}</span>${button('↑','block-up',b.id,'icon ghost')}${button('↓','block-down',b.id,'icon ghost')}${link(b.type==='test'?'test-edit':b.type==='practice'?'practice-edit':'block-edit','Изменить','ghost',{block:b.id,test:b.type==='test'?b.ref:null,practice:b.type==='practice'?b.ref:null})}${button('×','remove-block',b.id,'icon ghost')}</div><div class="block-content">${body}</div></section>`}
function questionCard(q,i){return `<section class="question" data-question="${q.id}"><div class="panel-head"><h3>Вопрос ${i+1}</h3>${button('Удалить','remove-question',q.id,'ghost')}</div>${select('Тип вопроса','questionType',[['single','Один правильный ответ'],['multiple','Несколько правильных ответов']],q.type)}${field('Вопрос *','questionText',q.text,'textarea')}<div class="eyebrow">ВАРИАНТЫ · ОТМЕТЬТЕ ПРАВИЛЬНЫЕ</div><div class="options">${q.options.map((o,j)=>optionRow(q.id,q.type,o,q.correct.includes(j))).join('')}</div>${button('＋ Вариант','add-option',q.id,'ghost')}${field('Объяснение ответа','explanation',q.explanation,'textarea')}</section>`}
function optionRow(id,type,text,correct){return `<label class="option"><input aria-label="Правильный вариант" type="${type==='multiple'?'checkbox':'radio'}" name="correct-${id}" ${correct?'checked':''}><input type="text" aria-label="Текст варианта" value="${esc(text)}"><button type="button" class="btn icon ghost" data-action="remove-option" aria-label="Удалить вариант">×</button></label>`}
function practiceCard(p,library){return `<article class="list-card"><div class="row"><span class="symbol">${p.type==='sql'?'SQL':'↔'}</span><div class="grow">${badge(types[p.type])}<h3>${esc(p.title)}</h3><p>${esc(p.instructions)}</p></div></div><div class="actions">${link('practice-edit','Редактировать','',{practice:p.id})}${library?(lesson?(lesson.practices.includes(p.id)?badge('Уже в уроке','green'):button('＋ Добавить в урок','attach-practice',p.id)):badge('Создайте урок для добавления')):button('Вставить в лекцию','embed-practice',p.id)}${!library?button('Убрать из урока','detach-practice',p.id,'ghost'):''}</div></article>`}
function testPreview(t){const instance=uid('preview');if(!t)return '<p>Тест недоступен</p>';return `<section class="panel preview-test" data-test="${t.id}"><div class="eyebrow">ПРОВЕРКА ПОНИМАНИЯ</div><h2>${esc(t.title)}</h2>${t.questions.map(q=>`<div data-q="${q.id}" style="margin-top:20px"><p>${esc(q.text)}</p>${q.options.map((o,i)=>`<label class="check"><input type="${q.type==='multiple'?'checkbox':'radio'}" name="${instance}-${q.id}" data-index="${i}">${esc(o)}</label>`).join('')}</div>`).join('')}<div class="bottom-actions">${button('Проверить ответы','check-test',t.id)}</div><div class="test-result" role="status"></div></section>`}
function practicePreview(p){if(!p)return '';return `<section class="panel preview-practice" data-practice="${p.id}"><div class="eyebrow">${esc(types[p.type])} · ДЕМОНСТРАЦИЯ</div><h2>${esc(p.title)}</h2><p class="muted" style="margin:15px 0">${esc(p.instructions)}</p><textarea class="code" aria-label="Учебное решение">${esc(p.type==='sql'?p.sql||'':`${p.method||'POST'} ${p.path||'/applications'}\n${p.headers||''}\n\n${p.body||''}`)}</textarea><div class="bottom-actions">${button('Выполнить демо','run-demo',p.id,'primary')}</div><div class="demo-result" role="status"></div></section>`}
function publicationChecks(){const flat=lessons();return [{ok:!!course.title.trim()&&!!course.description.trim(),text:'Название и описание курса заполнены',href:url('course-settings')},{ok:course.modules.length>0&&course.modules.every(m=>m.lessons.length),text:'В каждом модуле есть уроки',href:url('course-outline')},...flat.map(l=>({ok:l.blocks.length>0,text:l.title+' — лекция заполнена',href:url('lesson-lecture',{lesson:l.id})})),{ok:flat.length>0,text:'В программе есть хотя бы один урок',href:url('course-outline')} ]}
let dirty=false;
function toast(text){const box=document.getElementById('toast');box.className='toast';box.textContent=text;clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>{box.className='';box.textContent=''},4000)}
function values(form){return Object.fromEntries(new FormData(form))}
function collectPractice(){const f=document.getElementById('editor'),v=values(f);return {type:f.dataset.type,title:v.title,scenario:v.scenario,instructions:v.instructions,required:!!v.required,...(f.dataset.type==='http'?{method:v.method,path:v.path,query:v.query,headers:v.headers,auth:v.auth,bodyMode:v.bodyMode,body:v.body}:f.dataset.type==='sql'?{sql:v.sql}:{body:v.body}),steps:(v.steps||'').split('\n').filter(Boolean),checks:v.checks}}
function syncJson(){const el=document.getElementById('configJson');if(el)el.value=JSON.stringify({schemaVersion:1,...collectPractice()},null,2)}
function materialVisibility(){const f=document.getElementById('editor');if(f?.dataset.form!=='material')return;const t=f.elements.type.value;document.getElementById('materialLink').hidden=t!=='link';document.getElementById('materialFile').hidden=t!=='file';document.getElementById('materialTemplate').hidden=t!=='template'}
function error(message){let el=document.getElementById('formError');if(!el){el=document.createElement('div');el.id='formError';el.className='note error';el.setAttribute('role','alert');document.getElementById('editor').prepend(el)}el.textContent=message;el.scrollIntoView({block:'center'});return false}
document.addEventListener('submit',e=>{if(e.target.id!=='editor')return;e.preventDefault();const f=e.target,v=values(f),kind=f.dataset.form;let target='';if(['course','module','lesson','test','practice','material'].includes(kind)&&!v.title?.trim())return error('Заполните название.');
if(kind==='course'){if(!v.description.trim())return error('Добавьте краткое описание курса.');if(page==='course-new'){course={...v,id:uid('course'),status:'draft',modules:[]};course.visible=!!v.visible;state.courses.push(course)}else Object.assign(course,v,{visible:!!v.visible});target=url('course-outline',{course:course.id,lesson:null})}
if(kind==='module'){const fresh=page==='module-new';let m=fresh?{id:uid('module'),lessons:[]}:module;Object.assign(m,{title:v.title,description:v.description});if(!fresh)course.modules=course.modules.filter(x=>x.id!==m.id);const i=course.modules.findIndex(x=>'before:'+x.id===v.position);course.modules.splice(i<0?course.modules.length:i,0,m);target=url('course-outline')}
if(kind==='lesson'){const destination=course.modules.find(m=>m.id===v.module);if(!destination)return error('Сначала создайте модуль.');let l=page==='lesson-new'?{id:uid('lesson'),blocks:[],tests:[],practices:[],materials:[]}:lesson;Object.assign(l,{title:v.title,outcome:v.outcome,minutes:Number(v.minutes),free:!!v.free});if(!Number.isFinite(l.minutes)||l.minutes<1)return error('Укажите время прохождения от 1 минуты.');const previousIndex=destination.lessons.findIndex(x=>x.id===l.id);course.modules.forEach(m=>m.lessons=m.lessons.filter(x=>x.id!==l.id));destination.lessons.splice(previousIndex<0?destination.lessons.length:previousIndex,0,l);target=url('lesson-lecture',{lesson:l.id})}
if(kind==='block'){if(!v.text.trim())return error('Добавьте содержание блока.');let b=lesson.blocks.find(x=>x.id===params.get('block'));if(b)b.text=v.text;else lesson.blocks.push({id:uid('block'),type:f.dataset.type,text:v.text});target=url('lesson-lecture')}
if(kind==='test'){const qs=[...f.querySelectorAll('[data-question]')].map(q=>({id:q.dataset.question,type:q.querySelector('[name=questionType]').value,text:q.querySelector('[name=questionText]').value,options:[...q.querySelectorAll('.option input[type=text]')].map(i=>i.value),correct:[...q.querySelectorAll('.option')].flatMap((r,i)=>r.querySelector('input:first-child').checked?[i]:[]),explanation:q.querySelector('[name=explanation]').value}));if(!qs.length||qs.some(q=>!q.text.trim()||q.options.length<2||q.options.some(x=>!x.trim())||!q.correct.length))return error('В каждом вопросе нужны текст, минимум два непустых варианта и правильный ответ.');if(Number(v.passing)<1||Number(v.passing)>100)return error('Проходной результат должен быть от 1 до 100%.');let t=lesson.tests.find(x=>x.id===params.get('test'));if(!t){t={id:uid('test')};lesson.tests.push(t)}Object.assign(t,{title:v.title,passing:Number(v.passing),required:!!v.required,questions:qs});if(params.get('inline')==='1')lesson.blocks.push({id:uid('block'),type:'test',ref:t.id});target=url(params.get('inline')==='1'?'lesson-lecture':'lesson-tests')}
if(kind==='practice'){const p=collectPractice();if(!p.instructions.trim()||!p.checks.trim())return error('Заполните условие и ожидаемый результат.');if(p.type==='http'&&(!p.path.startsWith('/')||p.path.startsWith('//')||p.path.includes('://')))return error('Укажите относительный путь внутри учебного API, например /applications.');let existing=state.practices.find(x=>x.id===params.get('practice'));if(existing)Object.assign(existing,p);else{existing={id:uid('practice'),...p};state.practices.push(existing)}if(lesson&&!lesson.practices.includes(existing.id))lesson.practices.push(existing.id);if(params.get('inline')==='1')lesson.blocks.push({id:uid('block'),type:'practice',ref:existing.id});target=url(params.get('inline')==='1'?'lesson-lecture':'lesson-practice')}
if(kind==='material'){let a=lesson.materials.find(x=>x.id===params.get('material'));const file=f.elements.file.files[0];if(v.type==='link'&&safeUrl(v.value)==='#')return error('Укажите полный адрес с https:// или http://.');if(v.type==='file'&&!file&&!a?.fileName)return error('Выберите файл.');if(v.type==='template'&&!v.template.trim())return error('Добавьте содержание шаблона.');if(!a){a={id:uid('material')};lesson.materials.push(a)}Object.assign(a,{...v,fileName:file?.name||a.fileName});delete a.file;target=url('lesson-materials')}
if(save()){dirty=false;location.href=target}});
document.addEventListener('input',e=>{if(e.target.closest('#editor')){dirty=true;if(page==='practice-edit'&&e.target.id!=='configJson')syncJson()}if(e.target.id==='search'||e.target.id==='statusFilter')filterCourses();if(e.target.id==='practiceSearch'){let count=0;document.querySelectorAll('#practiceList>[data-title]').forEach(el=>{el.hidden=!el.dataset.title.includes(e.target.value.toLowerCase());if(!el.hidden)count++});document.getElementById('noPractice').hidden=!!count}});
document.addEventListener('change',e=>{if(e.target.name==='type')materialVisibility();if(e.target.id==='statusFilter')filterCourses();if(e.target.name==='questionType'){const q=e.target.closest('[data-question]');q.querySelectorAll('.option>input:first-child').forEach((i,n)=>{i.type=e.target.value==='multiple'?'checkbox':'radio';if(e.target.value==='single')i.checked=n===0})}if(e.target.dataset.move){const row=e.target.closest('[data-lesson]'),section=[...document.querySelectorAll('#orderModules>[data-module]')].find(x=>x.dataset.module===e.target.value);section.querySelector('.order-list').append(row);dirty=true}});
function filterCourses(){const term=document.getElementById('search').value.toLowerCase(),status=document.getElementById('statusFilter').value;let n=0;document.querySelectorAll('.course-card').forEach(el=>{el.hidden=!el.dataset.title.includes(term)||(status!=='all'&&el.dataset.status!==status);if(!el.hidden)n++});document.getElementById('noResults').hidden=!!n}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el)return;const action=el.dataset.action,id=el.dataset.id;
if(action==='reset'){state=structuredClone(seed);if(save())location.href='index.html';return}
if(action==='format'){const ta=document.querySelector('[name=text]'),start=ta.selectionStart,end=ta.selectionEnd,selected=ta.value.slice(start,end)||'текст',wrapped=id==='bold'?'**'+selected+'**':id==='italic'?'*'+selected+'*':'['+selected+'](https://example.com)';ta.setRangeText(wrapped,start,end,'end');ta.focus();dirty=true;return}
if(action==='add-question'){const wrap=document.getElementById('questions');wrap.insertAdjacentHTML('beforeend',questionCard({id:uid('q'),type:'single',text:'',options:['',''],correct:[0],explanation:''},wrap.children.length));dirty=true;return}
if(action==='remove-question'){el.closest('.question').remove();dirty=true;return}
if(action==='add-option'){el.closest('.question').querySelector('.options').insertAdjacentHTML('beforeend',optionRow(id,el.closest('.question').querySelector('[name=questionType]').value,'',false));dirty=true;return}
if(action==='remove-option'){el.closest('.option').remove();dirty=true;return}
if(action==='apply-json'){try{const j=JSON.parse(document.getElementById('configJson').value),f=document.getElementById('editor'),allowed=new Set(['schemaVersion','type','title','scenario','instructions','required','method','path','query','headers','auth','bodyMode','body','sql','steps','checks']);if(Object.keys(j).some(k=>!allowed.has(k)))throw new Error('Допускаются только учебные поля. Ресурсы и политики настраивает платформа.');if(j.schemaVersion!==1||j.type!==f.dataset.type)throw new Error('Версия или тип не совпадает с этим упражнением.');if(!scenarios[j.type].some(s=>s[0]===j.scenario))throw new Error('Выберите зарегистрированный сценарий.');for(const [k,v]of Object.entries(j)){const input=f.elements.namedItem(k);if(!input)continue;if(k==='required'){if(typeof v!=='boolean')throw new Error('required должен быть true или false.');input.checked=v}else if(k==='steps'){if(!Array.isArray(v)||v.some(x=>typeof x!=='string'))throw new Error('steps должен быть массивом строк.');input.value=v.join('\n')}else{if(typeof v!=='string')throw new Error(k+' должен быть строкой.');if(input.tagName==='SELECT'&&![...input.options].some(o=>o.value===v))throw new Error('Недопустимое значение '+k);input.value=v}}document.getElementById('jsonError').textContent='';dirty=true;syncJson();toast('JSON применён к полям упражнения.')}catch(err){document.getElementById('jsonError').textContent=err.message}return}
if(action==='lesson-up'||action==='lesson-down'){const row=el.closest('[data-lesson]');if(action==='lesson-up'&&row.previousElementSibling)row.parentNode.insertBefore(row,row.previousElementSibling);if(action==='lesson-down'&&row.nextElementSibling)row.parentNode.insertBefore(row.nextElementSibling,row);dirty=true;return}
if(action==='module-up'||action==='module-down'){const row=el.closest('[data-module]');if(action==='module-up'&&row.previousElementSibling)row.parentNode.insertBefore(row,row.previousElementSibling);if(action==='module-down'&&row.nextElementSibling)row.parentNode.insertBefore(row.nextElementSibling,row);dirty=true;return}
if(action==='save-order'){const old=course.modules.flatMap(m=>m.lessons);course.modules=[...document.querySelectorAll('#orderModules>[data-module]')].map(sec=>{const m=course.modules.find(x=>x.id===sec.dataset.module);return {...m,lessons:[...sec.querySelectorAll('[data-lesson]')].map(r=>old.find(l=>l.id===r.dataset.lesson))}});if(save()){dirty=false;location.href=url('course-outline')}return}
if(action==='run-demo'){const p=state.practices.find(p=>p.id===id),section=el.closest('.preview-practice');section.querySelector('.demo-result').innerHTML=`<div class="result">${p.type==='sql'?'Демо-результат · запрос не исполнялся\n\nid  | name\n42  | Анна\n57  | Максим':'Демо-ответ · сетевой запрос не выполнялся\n\nHTTP/1.1 200 OK\nContent-Type: application/json\n\n{"id": "application-57", "status": "NEW"}'}</div>`;return}
if(action==='check-test'){const t=lesson.tests.find(t=>t.id===id),section=el.closest('.preview-test');let correct=0;const explanations=[];section.querySelectorAll('[data-q]').forEach(q=>{const def=t.questions.find(x=>x.id===q.dataset.q),chosen=[...q.querySelectorAll('input:checked')].map(i=>Number(i.dataset.index));const ok=chosen.length===def.correct.length&&chosen.every(i=>def.correct.includes(i));if(ok)correct++;explanations.push((ok?'✓ ':'○ ')+esc(def.explanation||'Сопоставьте ответ с материалом урока.'))});section.querySelector('.test-result').innerHTML=`<div class="note">Верно: ${correct} из ${t.questions.length}<br>${explanations.join('<br>')}</div>`;return}
if(action==='duplicate-lesson'){const copy=structuredClone(lesson);copy.id=uid('lesson');copy.title+=' · копия';copy.tests.forEach(t=>{const old=t.id;t.id=uid('test');copy.blocks.filter(b=>b.type==='test'&&b.ref===old).forEach(b=>b.ref=t.id)});copy.blocks.forEach(b=>b.id=uid('block'));module.lessons.push(copy);if(save())location.href=url('lesson-lecture',{lesson:copy.id});return}
if(action==='attach-practice'){if(!lesson.practices.includes(id))lesson.practices.push(id);save();render();toast('Упражнение добавлено в текущий урок.');return}
if(action==='embed-test'||action==='embed-practice'){const type=action==='embed-test'?'test':'practice';if(!lesson.blocks.some(b=>b.type===type&&b.ref===id))lesson.blocks.push({id:uid('block'),type,ref:id});if(save())location.href=url('lesson-lecture');return}
if(action==='detach-practice'){lesson.practices=lesson.practices.filter(x=>x!==id);lesson.blocks=lesson.blocks.filter(b=>!(b.type==='practice'&&b.ref===id));save();render();toast('Привязка удалена. Упражнение осталось в библиотеке.');return}
if(action==='remove-block'){lesson.blocks=lesson.blocks.filter(b=>b.id!==id);save();render();return}
if(action==='block-up'||action==='block-down'){const i=lesson.blocks.findIndex(b=>b.id===id),j=i+(action==='block-up'?-1:1);if(j>=0&&j<lesson.blocks.length)[lesson.blocks[i],lesson.blocks[j]]=[lesson.blocks[j],lesson.blocks[i]];save();render();return}
if(action==='publish'){if(publicationChecks().some(c=>!c.ok))return;course.status='published';save();render();toast('Курс опубликован в локальном макете.');return}
if(action==='confirm-delete'){const entity=params.get('entity');if(entity==='module')course.modules=course.modules.filter(m=>m.id!==id);if(entity==='lesson')course.modules.forEach(m=>m.lessons=m.lessons.filter(l=>l.id!==id));if(entity==='test'){lesson.tests=lesson.tests.filter(t=>t.id!==id);lesson.blocks=lesson.blocks.filter(b=>!(b.type==='test'&&b.ref===id))}if(entity==='material')lesson.materials=lesson.materials.filter(a=>a.id!==id);if(save())location.href=url(entity==='test'?'lesson-tests':entity==='material'?'lesson-materials':'course-outline',{lesson:entity==='lesson'||entity==='module'?null:lesson.id});return}
});
function bindDrag(){let dragged;document.querySelectorAll('[draggable]').forEach(row=>{row.addEventListener('dragstart',e=>{dragged=row;e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('text/plain',row.dataset.lesson)});row.addEventListener('dragover',e=>{e.preventDefault();row.classList.add('drag-over')});row.addEventListener('dragleave',()=>row.classList.remove('drag-over'));row.addEventListener('drop',e=>{e.preventDefault();row.classList.remove('drag-over');if(dragged&&dragged!==row){row.parentNode.insertBefore(dragged,row);const m=row.closest('[data-module]').dataset.module;dragged.querySelector('select').value=m;dirty=true}})})}
window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue=''}});
if(!lesson&&['lesson-lecture','lesson-tests','lesson-practice','lesson-materials','lesson-preview','lesson-settings','test-edit','block-add','block-edit','material-edit'].includes(page))shell(empty('Сначала создайте урок','В программе пока нет уроков.',link('course-outline','В программу','primary')));else render();
})();
